function findReviewTarget(r){if(!r||!SETS[r.mode])return false;mode=r.mode;const ss=SETS[mode]||[],found=ss.find(s=>Array.isArray(s.items)&&s.items.includes(r.value));setId=found?.id||ss[0]?.id||'';currentIndex=0;syncSetControls();syncPaperStyle();loadItems();const idx=items.indexOf(r.value);if(idx>=0)currentIndex=idx;syncSubjectButtons();clearCanvas(false);renderAll();showView('writeView');setTimeout(()=>{resizeCanvas();restoreDraftForCurrent()},40);return true}
function goReview(){if(!confirmLeaveWriting())return;saveDraftNow();const list=reviewEntries().sort((a,b)=>(Number(a.lastPracticed)||0)-(Number(b.lastPracticed)||0));if(list.length){if(!findReviewTarget(list[0]))toast('暫時找不到這個複習內容');return}const mw=mathWeakEntries();if(mw.length){startMathWeak(mw[0].key);return}toast('🎉 目前沒有需要加強的內容！')}
function dailyTrack(){return ['english','zhuyin','number','math']}
function nextDailyMode(){const c=child(),day=localDay(),target=state.taskTarget||5;return dailyTrack().find(m=>(c.daily?.[day]?.[m]||0)<target)||''}
function renderSmartDaily(){const bar=$('#smartDailyBar');if(!bar)return;const c=child(),day=localDay(),target=state.taskTarget||5,track=dailyTrack(),doneUnits=track.reduce((sum,m)=>sum+Math.min(target,Number(c.daily?.[day]?.[m])||0),0),total=target*track.length,pct=total?Math.round(doneUnits/total*100):0,next=nextDailyMode(),reviewN=reviewEntries(c).length+mathWeakEntries(c).length;$('#dailyPlanProgress').style.width=pct+'%';$('#dailyPlanText').textContent=next?`完成 ${doneUnits} / ${total} 題・下一站：${MODE_LABEL[next]}`:`今日課表完成！${reviewN?'還有加強複習':''}`;$('#reviewCount').textContent=reviewN;$('#smartContinueBtn').textContent=next?`▶ 繼續 ${MODE_LABEL[next]}`:(reviewN?'🧠 開始加強複習':'🎉 今日已完成');$('#smartContinueBtn').disabled=!next&&!reviewN}
function renderMathQuestionNav(){const wrap=$('#mathQuestionNav'),grid=$('#mathNavGrid'),summary=$('#mathNavSummary');if(!wrap||!grid||mode!=='math'){if(wrap)wrap.hidden=true;return}wrap.hidden=false;const session=child().mathSession||{},completed=session.completed||{},checks=session.checks||{};const done=mathProblems.filter(q=>completed[q.id]).length,correct=mathProblems.filter(q=>checks[q.id]?.result==='correct').length;summary.textContent=`完成 ${done}/${mathProblems.length}・答對 ${correct}`;grid.innerHTML=mathProblems.map((q,i)=>{const ck=checks[q.id]?.result||'',cl=i===currentIndex?' current':'';const stateCl=ck==='correct'?' correct':ck==='wrong'?' wrong':completed[q.id]?' done':'';const mark=ck==='correct'?'✓':ck==='wrong'?'×':completed[q.id]?'✓':'○';return `<button class="math-nav-btn${cl}${stateCl}" type="button" data-math-nav="${i}" aria-label="第 ${i+1} 題">${i+1}<small>${mark}</small></button>`}).join('');grid.querySelectorAll('[data-math-nav]').forEach(b=>b.addEventListener('click',()=>jumpMathQuestion(Number(b.dataset.mathNav)))) }
function jumpMathQuestion(index){if(mode!=='math'||!Number.isInteger(index)||index<0||index>=mathProblems.length||index===currentIndex)return;if(!confirmLeaveWriting())return;saveDraftNow();currentIndex=index;if(child().mathSession){child().mathSession.index=index;save()}clearCanvas(false);renderAll();setTimeout(()=>{resizeCanvas();restoreDraftForCurrent()},30)}
function renderWriting(){
 renderMathQuestionNav();
 const isMath=mode==='math';document.body.classList.toggle('math-tablet',isMath);
 if(isMath){const q=currentMathProblem(),question=mathQuestionText(q),session=child().mathSession||{},doneN=Object.keys(session.completed||{}).length,check=q?(session.checks?.[q.id]||null):null;if($('#childMathType'))$('#childMathType').value=$('#mathType').value;if($('#childMathMax'))$('#childMathMax').value=$('#mathMax').value;if($('#childMathCount'))$('#childMathCount').value=$('#mathCount').value;$('#writeTarget').textContent=question||'—';$('#writeTarget').classList.add('math-target');$('#canvasGuide').textContent='';if($('#focusTarget'))$('#focusTarget').textContent=question||'—';if($('#focusPoints'))$('#focusPoints').textContent=child().points;$('#modeBadge').innerHTML=`加減法｜智慧平板 <span class="math-progress-state">本份 ${doneN}/${mathProblems.length}</span>`;$('#setHint').textContent=q?`第 ${currentIndex+1} 題，共 ${mathProblems.length} 題；每題筆跡會自動保存。`:'請重新產生數學題目';$('#positionText').textContent=mathProblems.length?`${currentIndex+1} / ${mathProblems.length}`:'0 / 0';$('#todayModeCount').textContent=todayCount('math');if($('#markReviewBtn'))$('#markReviewBtn').style.display='none';const ai=$('#mathAnswerInput'),st=$('#mathCheckStatus');if(ai&&q){ai.value=session.answers?.[q.id]??'';ai.disabled=!!session.completed?.[q.id]}if(st){st.className='math-check-status'+(check?.result?` ${check.result}`:'');st.textContent=check?.result==='correct'?'✅ 答對了！':check?.result==='wrong'?`再想想～已嘗試 ${check.attempts||1} 次`:(session.completed?.[q?.id]?'✅ 已完成這題':'尚未核對')}$('#completeBtn').textContent=session.completed?.[q?.id]?'✅ 這題已完成':'完成這一題 ⭐';renderMathQuestionNav();return}
 $('#writeTarget').classList.remove('math-target');const set=currentSets().find(x=>x.id===setId);$('#writeTarget').textContent=current()||'—';$('#canvasGuide').textContent=current()||'';if($('#focusTarget'))$('#focusTarget').textContent=current()||'';if($('#focusPoints'))$('#focusPoints').textContent=child().points;$('#modeBadge').textContent=`${MODE_LABEL[mode]}｜${set?.name||'自訂'}`;$('#setHint').textContent=set?.hint||'自訂練習內容';$('#positionText').textContent=items.length?`${currentIndex+1} / ${items.length}`:'0 / 0';$('#todayModeCount').textContent=todayCount();if($('#markReviewBtn')){$('#markReviewBtn').style.display='';const r=child().weakItems?.[reviewKey(mode,current())];$('#markReviewBtn').textContent=r?'🧠 已在加強清單':'🧠 加強這題'}
}

// ===== V2.2 智慧成長 / 作品相簿 / 數學資料 / PWA =====
const V20_GALLERY_DB='KidsWritingGalleryV20',V20_GALLERY_STORE='artworks',V21_MATH_DRAFT_STORE='mathDrafts';
let v20GalleryDbPromise=null,deferredInstallPrompt=null;
function openGalleryDB(){
 if(!('indexedDB' in window))return Promise.reject(new Error('IndexedDB unavailable'));
 if(v20GalleryDbPromise)return v20GalleryDbPromise;
 v20GalleryDbPromise=new Promise((resolve,reject)=>{const req=indexedDB.open(V20_GALLERY_DB,2);req.onupgradeneeded=()=>{const db=req.result;if(!db.objectStoreNames.contains(V20_GALLERY_STORE)){const s=db.createObjectStore(V20_GALLERY_STORE,{keyPath:'id'});s.createIndex('childId','childId',{unique:false});s.createIndex('createdAt','createdAt',{unique:false})}if(!db.objectStoreNames.contains(V21_MATH_DRAFT_STORE)){const d=db.createObjectStore(V21_MATH_DRAFT_STORE,{keyPath:'id'});d.createIndex('childId','childId',{unique:false});d.createIndex('sessionId','sessionId',{unique:false})}};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error||new Error('open db failed'))});return v20GalleryDbPromise;
}
async function getArtworksForChild(childId){try{const db=await openGalleryDB();return await new Promise((resolve,reject)=>{const tx=db.transaction(V20_GALLERY_STORE,'readonly'),req=tx.objectStore(V20_GALLERY_STORE).getAll();req.onsuccess=()=>resolve((req.result||[]).filter(x=>x.childId===childId).sort((a,b)=>b.createdAt-a.createdAt));req.onerror=()=>reject(req.error)})}catch(e){return[]}}
async function getAllStoreRecords(storeName){try{const db=await openGalleryDB();return await new Promise((resolve,reject)=>{const tx=db.transaction(storeName,'readonly'),req=tx.objectStore(storeName).getAll();req.onsuccess=()=>resolve(req.result||[]);req.onerror=()=>reject(req.error)})}catch(e){return[]}}
function currentMathDraftId(){const q=currentMathProblem(),session=child().mathSession;if(!q||!session)return'';return `${child().id}|${session.id}|${q.id}`}
async function saveMathDraftNow(){if(mode!=='math'||!canvasHistory.length)return false;const id=currentMathDraftId(),session=child().mathSession,q=currentMathProblem();if(!id||!session||!q||session.completed?.[q.id])return false;try{const db=await openGalleryDB(),rec={id,childId:child().id,sessionId:session.id,questionId:q.id,updatedAt:Date.now(),image:canvas.toDataURL('image/png')};await new Promise((resolve,reject)=>{const tx=db.transaction(V21_MATH_DRAFT_STORE,'readwrite');tx.objectStore(V21_MATH_DRAFT_STORE).put(rec);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)});setDraftPill(true);return true}catch(e){console.warn('數學筆跡暫存失敗',e);return false}}
async function restoreMathDraftForCurrent(){const id=currentMathDraftId();if(!id)return;try{const db=await openGalleryDB(),rec=await new Promise((resolve,reject)=>{const tx=db.transaction(V21_MATH_DRAFT_STORE,'readonly'),req=tx.objectStore(V21_MATH_DRAFT_STORE).get(id);req.onsuccess=()=>resolve(req.result||null);req.onerror=()=>reject(req.error)});if(!rec?.image)return;const r=canvas.getBoundingClientRect();if(!r.width)return;const im=new Image();im.onload=()=>{ctx.clearRect(0,0,r.width,r.height);ctx.drawImage(im,0,0,r.width,r.height);canvasHistory=[rec.image];setDraftPill(true)};im.src=rec.image}catch(e){console.warn('數學筆跡還原失敗',e)}}
async function deleteCurrentMathDraft(){const id=currentMathDraftId();if(!id)return;try{const db=await openGalleryDB();await new Promise((resolve,reject)=>{const tx=db.transaction(V21_MATH_DRAFT_STORE,'readwrite');tx.objectStore(V21_MATH_DRAFT_STORE).delete(id);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)})}catch(e){}}
async function deleteMathDraftsForSession(childId,sessionId){if(!childId||!sessionId)return;try{const db=await openGalleryDB(),all=await getAllStoreRecords(V21_MATH_DRAFT_STORE);await new Promise((resolve,reject)=>{const tx=db.transaction(V21_MATH_DRAFT_STORE,'readwrite'),st=tx.objectStore(V21_MATH_DRAFT_STORE);all.filter(x=>x.childId===childId&&x.sessionId===sessionId).forEach(x=>st.delete(x.id));tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)})}catch(e){}}
async function replaceStoreRecords(storeName,records){const db=await openGalleryDB();await new Promise((resolve,reject)=>{const tx=db.transaction(storeName,'readwrite'),st=tx.objectStore(storeName);st.clear();(Array.isArray(records)?records:[]).forEach(r=>{if(r&&r.id)st.put(r)});tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)})}
async function deleteAllChildStoredData(childId){try{const db=await openGalleryDB(),arts=await getAllStoreRecords(V20_GALLERY_STORE),drafts=await getAllStoreRecords(V21_MATH_DRAFT_STORE);await new Promise((resolve,reject)=>{const tx=db.transaction([V20_GALLERY_STORE,V21_MATH_DRAFT_STORE],'readwrite'),a=tx.objectStore(V20_GALLERY_STORE),d=tx.objectStore(V21_MATH_DRAFT_STORE);arts.filter(x=>x.childId===childId).forEach(x=>a.delete(x.id));drafts.filter(x=>x.childId===childId).forEach(x=>d.delete(x.id));tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)})}catch(e){console.warn('清除孩子本機作品失敗',e)}}
async function deleteArtwork(id){try{const db=await openGalleryDB();await new Promise((resolve,reject)=>{const tx=db.transaction(V20_GALLERY_STORE,'readwrite');tx.objectStore(V20_GALLERY_STORE).delete(id);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)});renderGallery()}catch(e){toast('無法刪除作品')}}
async function trimGallery(childId){const all=await getArtworksForChild(childId),limit=state.galleryLimit||50;if(all.length<=limit)return;try{const db=await openGalleryDB();await new Promise((resolve,reject)=>{const tx=db.transaction(V20_GALLERY_STORE,'readwrite'),s=tx.objectStore(V20_GALLERY_STORE);all.slice(limit).forEach(x=>s.delete(x.id));tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)})}catch(e){}}
function compositeArtworkDataURL(){
 try{const out=document.createElement('canvas');out.width=canvas.width;out.height=canvas.height;const c=out.getContext('2d'),ratio=Math.max(1,window.devicePixelRatio||1),w=out.width,h=out.height;c.fillStyle='#fffefc';c.fillRect(0,0,w,h);c.strokeStyle='#eadde4';c.lineWidth=Math.max(1,ratio);c.setLineDash([7*ratio,6*ratio]);c.beginPath();c.moveTo(w/2,0);c.lineTo(w/2,h);c.moveTo(0,h/2);c.lineTo(w,h/2);c.stroke();c.setLineDash([]);const v=String(current()||'');if(v){c.save();c.globalAlpha=.12;c.fillStyle='#5f4866';c.textAlign='center';c.textBaseline='middle';c.font=`900 ${Math.round(Math.min(w,h)*.55)}px "Microsoft JhengHei","PingFang TC",sans-serif`;c.fillText(v,w/2,h/2);c.restore()}c.drawImage(canvas,0,0);const maxDim=900,scale=Math.min(1,maxDim/Math.max(w,h));if(scale<1){const small=document.createElement('canvas');small.width=Math.max(1,Math.round(w*scale));small.height=Math.max(1,Math.round(h*scale));small.getContext('2d').drawImage(out,0,0,small.width,small.height);return small.toDataURL('image/jpeg',.72)}return out.toDataURL('image/jpeg',.72)}catch(e){return''}}
async function saveArtworkSnapshot(){if(!state.autoGallery||!canvasHistory.length||!current())return false;const image=compositeArtworkDataURL();if(!image)return false;try{const c=child(),db=await openGalleryDB(),rec={id:`${c.id}-${Date.now()}-${Math.random().toString(36).slice(2,6)}`,childId:c.id,childName:c.name,mode,value:String(current()),setId,createdAt:Date.now(),day:localDay(),image};await new Promise((resolve,reject)=>{const tx=db.transaction(V20_GALLERY_STORE,'readwrite');tx.objectStore(V20_GALLERY_STORE).put(rec);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)});await trimGallery(c.id);return true}catch(e){console.warn('作品保存失敗',e);return false}}
async function renderGallery(){const grid=$('#galleryGrid'),empty=$('#galleryEmpty');if(!grid||!empty)return;const all=await getArtworksForChild(child().id);empty.style.display=all.length?'none':'block';grid.innerHTML=all.slice(0,24).map(a=>`<div class="artwork-card"><img loading="lazy" src="${esc(safeDataImage(a.image))}" alt="${esc(a.value)} 手寫作品"><div class="artwork-meta"><strong>${esc(MODE_LABEL[a.mode]||'練習')}｜${esc(a.value)}</strong><small>${new Date(a.createdAt).toLocaleString('zh-TW')}</small><div class="artwork-actions">${parentUnlocked?`<button class="btn soft" type="button" data-del-art="${esc(a.id)}">刪除</button>`:''}</div></div></div>`).join('');grid.querySelectorAll('[data-del-art]').forEach(b=>b.addEventListener('click',()=>{if(confirm('刪除這張作品嗎？'))deleteArtwork(b.dataset.delArt)}))}
function autoReviewKey(){return reviewKey(mode,current())}
function trackStruggle(points=1,reason='修改較多'){if(!state.autoWeak||!current())return;if(mode==='math'){const q=currentMathProblem();if(q&&points>=2)noteMathWrong(q,reason);return;}const c=child(),key=autoReviewKey();c.friction=c.friction||{};c.friction[key]=(Number(c.friction[key])||0)+points;if(c.friction[key]>=3&&!c.weakItems[key]){c.weakItems[key]={mode,value:current(),markedAt:Date.now(),times:1,success:0,auto:true,reason};save();renderSmartDaily();toast('🧠 這題修改比較多，已自動加入加強複習')}else save()}
function resetFrictionAfterSuccess(){if(mode==='math'||!current())return;const c=child();if(c.friction)c.friction[autoReviewKey()]=0}
function noteMathWrong(q=currentMathProblem(),reason='答案需要再練習'){if(!q)return;const c=child(),info=mathSkillInfo(q,state.mathMax),old=c.mathWeakTypes?.[info.key]||{};c.mathWeakTypes=c.mathWeakTypes||{};c.mathWeakTypes[info.key]={label:info.label,wrong:(Number(old.wrong)||0)+1,success:0,lastWrong:Date.now(),reason};save();renderSmartDaily()}
function noteMathCorrect(q=currentMathProblem()){if(!q)return;const c=child(),info=mathSkillInfo(q,state.mathMax),old=c.mathWeakTypes?.[info.key];if(!old)return;const success=(Number(old.success)||0)+1;if(success>=3)delete c.mathWeakTypes[info.key];else c.mathWeakTypes[info.key]=Object.assign({},old,{success,lastCorrect:Date.now()});save()}
function startMathWeak(key){const item=mathWeakEntries().find(x=>x.key===key);if(!item)return false;const parts=key.split(':'),op=parts[0],range=Number(parts[2])||20;$('#mathType').value=op;$('#mathMax').value=String(range);state.mathType=op;state.mathMax=range;save();mode='math';syncSubjectButtons();syncSetControls();syncPaperStyle();generateMath(true);clearCanvas(false);renderAll();showView('writeView');setTimeout(()=>{resizeCanvas();restoreDraftForCurrent()},40);return true}
function weekStats(c=child()){const modes={english:0,zhuyin:0,number:0,math:0,chinese:0,custom:0};let total=0;for(let i=0;i<7;i++){const d=new Date();d.setDate(d.getDate()-i);const x=c.daily?.[localDay(d)]||{};Object.keys(modes).forEach(m=>{const n=Number(x[m])||0;modes[m]+=n;total+=n})}return{modes,total}}
function growthRecommendation(c=child()){const w=reviewEntries(c).length+mathWeakEntries(c).length,ws=weekStats(c),core=['english','zhuyin','number','math'],lowest=core.slice().sort((a,b)=>ws.modes[a]-ws.modes[b])[0];if(w>=5)return `目前有 ${w} 個加強內容，建議先從「智慧加強複習」開始。`;if(ws.total===0)return '這週還沒有練習紀錄，可以先完成今天的第一個小任務。';return `這週相對較少的是「${MODE_LABEL[lowest]}」，下次可以多練幾題。`}
function renderGrowthReport(){const el=$('#growthReport');if(!el)return;const c=child(),ws=weekStats(c),w=reviewEntries(c).length+mathWeakEntries(c).length;el.innerHTML=`<div class="growth-summary"><div class="mini"><strong>${ws.total}</strong><span>7 天完成</span></div><div class="mini"><strong>${streak(c)}</strong><span>連續天數</span></div><div class="mini"><strong>${w}</strong><span>加強項目</span></div></div><div class="report-breakdown">${[['english','英文'],['zhuyin','注音'],['number','數字'],['math','加減']].map(([m,n])=>`<div class="report-chip"><strong>${ws.modes[m]||0}</strong><span>${n}</span></div>`).join('')}</div><div class="report-tip">💡 ${esc(growthRecommendation(c))}</div>`}
function renderGrowthView(){const c=child(),day=localDay(),target=state.taskTarget||5,track=dailyTrack();if($('#growthPoints'))$('#growthPoints').textContent=c.points;if($('#v20DailyPlanGrid'))$('#v20DailyPlanGrid').innerHTML=track.map(m=>{const n=Number(c.daily?.[day]?.[m])||0,done=n>=target;return `<div class="daily-plan-item ${done?'done':''}"><strong>${Math.min(n,target)} / ${target}</strong><small>${MODE_LABEL[m]} ${done?'✓':''}</small></div>`}).join('');if($('#v20GrowthSummary'))$('#v20GrowthSummary').innerHTML=`<div class="mini"><strong>${c.done}</strong><span>累積完成</span></div><div class="mini"><strong>${streak(c)}</strong><span>連續天數</span></div><div class="mini"><strong>${badges(c).filter(x=>x.ok).length}</strong><span>徽章</span></div>`;const goal=state.gifts.find(g=>String(g.id)===String(c.goalGiftId));if($('#v20GoalMini'))$('#v20GoalMini').textContent=goal?(c.points>=goal.cost?`🎁 已存夠「${goal.name}」！`:`🎁 禮物目標：${goal.name}，還差 ${goal.cost-c.points} 點`):'🎁 還沒有設定禮物目標，可到「我的禮物」選一個。';const list=reviewEntries(c).sort((a,b)=>(Number(a.lastPracticed)||0)-(Number(b.lastPracticed)||0)),mathList=mathWeakEntries(c);if($('#v20WeakList'))$('#v20WeakList').innerHTML=(list.length||mathList.length)?list.slice(0,10).map(r=>`<div class="weak-item"><div><strong>${esc(r.value)}</strong> <span class="auto-weak-badge">${r.auto?'🤖 自動':'🧠 加強'}</span><br><small>${esc(MODE_LABEL[r.mode]||r.mode)}・完成 ${Number(r.success)||0}/3 次</small></div><button class="btn soft" type="button" data-review-key="${esc(r.key)}">練習</button></div>`).join('')+mathList.slice(0,6).map(r=>`<div class="weak-item"><div><strong>${esc(r.label)}</strong> <span class="math-weak-badge">➕ 錯題型</span><br><small>答錯 ${Number(r.wrong)||0} 次・連續答對 ${Number(r.success)||0}/3 次可畢業</small></div><button class="btn soft" type="button" data-math-weak="${esc(r.key)}">練同型</button></div>`).join(''):'<div class="gallery-empty">目前沒有需要加強的內容，太棒了！ 🎉</div>';$('#v20WeakList')?.querySelectorAll('[data-review-key]').forEach(b=>b.addEventListener('click',()=>{const r=reviewEntries(c).find(x=>x.key===b.dataset.reviewKey);if(r)findReviewTarget(r)}));$('#v20WeakList')?.querySelectorAll('[data-math-weak]').forEach(b=>b.addEventListener('click',()=>startMathWeak(b.dataset.mathWeak)));renderGallery()}
async function updateStorageHealth(){const box=$('#storageHealth'),text=$('#storageHealthText');if(!box||!text)return;box.classList.remove('warn','danger');if(!navigator.storage?.estimate){text.textContent='此瀏覽器未提供容量資訊';return}try{const e=await navigator.storage.estimate(),used=Number(e.usage)||0,quota=Number(e.quota)||0,pct=quota?used/quota*100:0,fmt=n=>n>=1073741824?(n/1073741824).toFixed(1)+' GB':(n/1048576).toFixed(1)+' MB';text.textContent=quota?`${fmt(used)} / ${fmt(quota)}（${pct.toFixed(1)}%）`:`已使用 ${fmt(used)}`;box.classList.toggle('warn',pct>=70&&pct<90);box.classList.toggle('danger',pct>=90)}catch(e){text.textContent='無法取得儲存空間資訊'}}
