function printPracticeOnly(){
  if(printBusy)return;printBusy=true;
  renderPrint();
  const portal=$('#printPortal'),sheet=$('#printSheet');
  if(!portal||!sheet){printBusy=false;return;}
  portal.innerHTML='';
  const clone=sheet.cloneNode(true);
  clone.removeAttribute('id');
  const pages=[...clone.querySelectorAll('.practice-page')];if(pages.length){const chosen=[...selectedPrintPages].filter(n=>n>=1&&n<=pages.length);if(!chosen.length){alert('請至少選擇 1 頁再列印。');printBusy=false;return}pages.forEach((pg,i)=>{if(!selectedPrintPages.has(i+1))pg.remove()})}
  if($('#inkSave').checked)clone.classList.add('ink-save-print');
  portal.appendChild(clone);
  document.body.classList.add('printing-practice');
  const cleanup=()=>{document.body.classList.remove('printing-practice');portal.innerHTML='';printBusy=false;window.removeEventListener('afterprint',cleanup)};
  window.addEventListener('afterprint',cleanup);
  requestAnimationFrame(()=>requestAnimationFrame(()=>window.print()));
  setTimeout(()=>{if(document.body.classList.contains('printing-practice'))cleanup()},5000);
}
