function mathRangeBucket(max){return max<=10?'10':max<=20?'20':max<=50?'50':'100'}
function mathSkillInfo(q,max=state.mathMax){if(!q)return{key:'',label:''};const range=mathRangeBucket(max);if(q.op==='add'){const carry=max>=20&&((q.a%10)+(q.b%10)>=10);return{key:`add:${carry?'carry':'plain'}:${range}`,label:`${range} 以內・${carry?'進位加法':'基礎加法'}`}}const borrow=max>=20&&(q.a%10<q.b%10);return{key:`sub:${borrow?'borrow':'plain'}:${range}`,label:`${range} 以內・${borrow?'退位減法':'基礎減法'}`}}
function mathWeakEntries(c=child()){c.mathWeakTypes=(c.mathWeakTypes&&typeof c.mathWeakTypes==='object')?c.mathWeakTypes:{};return Object.entries(c.mathWeakTypes).map(([key,v])=>Object.assign({key},v||{})).filter(x=>x.label&&(Number(x.wrong)||0)>0).sort((a,b)=>(Number(b.wrong)||0)-(Number(a.wrong)||0))}
function shuffled(arr){const a=arr.slice();for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function buildMathPool(op,max){const out=[];if(op==='add'){for(let a=0;a<=max;a++)for(let b=0;b<=max-a;b++)out.push({a,b,op:'add',ans:a+b})}else{for(let a=0;a<=max;a++)for(let b=0;b<=a;b++)out.push({a,b,op:'sub',ans:a-b})}return out}
function difficultyOrder(pool,max){const buckets=[[],[],[]];pool.forEach(q=>{const score=q.op==='add'?q.ans/max:q.a/max;const bi=score<.34?0:score<.67?1:2;buckets[bi].push(q)});buckets.forEach((b,i)=>buckets[i]=shuffled(b));const out=[];let keep=true;while(keep){keep=false;for(const b of buckets){if(b.length){out.push(b.pop());keep=true}}}return out}
function selectMathForOp(op,n,max,c){let pool=difficultyOrder(buildMathPool(op,max),max),chosen=[],used=new Set();const weak=new Set(mathWeakEntries(c).map(x=>x.key));const weakPool=pool.filter(q=>weak.has(mathSkillInfo(q,max).key)),weakTake=Math.min(weakPool.length,Math.max(0,Math.round(n*.25)));for(const q of weakPool.slice(0,weakTake)){const k=`${q.op}:${q.a}:${q.b}`;if(!used.has(k)){chosen.push(q);used.add(k)}}for(const q of pool){if(chosen.length>=n)break;const k=`${q.op}:${q.a}:${q.b}`;if(!used.has(k)){chosen.push(q);used.add(k)}}return chosen.slice(0,n)}
function generateMath(force=false){const max=+$('#mathMax').value,count=Math.max(10,Math.min(50,+$('#mathCount').value||20)),type=$('#mathType').value,c=child(),sig=`${localDay()}|${type}|${max}|${count}`;if(!force&&c.mathSession&&c.mathSession.signature===sig&&Array.isArray(c.mathSession.problems)&&c.mathSession.problems.length===count){mathProblems=c.mathSession.problems.map(x=>Object.assign({},x));mathRunId=c.mathSession.id||'saved';currentIndex=Math.max(0,Math.min(mathProblems.length-1,Number(c.mathSession.index)||0));return mathProblems}const oldId=c.mathSession?.id;if(force&&oldId)deleteMathDraftsForSession(c.id,oldId);const addN=type==='add'?count:type==='sub'?0:Math.ceil(count/2),subN=type==='sub'?count:type==='add'?0:count-addN;let selected=[...selectMathForOp('add',addN,max,c),...selectMathForOp('sub',subN,max,c)];selected=shuffled(selected).slice(0,count).map((q,i)=>Object.assign({id:`q${i+1}-${q.op}-${q.a}-${q.b}`},q));mathRunId=`m${Date.now()}-${Math.random().toString(36).slice(2,7)}`;mathProblems=selected;currentIndex=0;c.mathSession={id:mathRunId,signature:sig,createdAt:Date.now(),problems:selected,index:0,answers:{},checks:{},completed:{}};save();return mathProblems}
// unfinished handwriting draft
function draftKey(){return `${child().id}|${mode}|${setId}|${currentIndex}|${current()}`}
function setDraftPill(show){const p=$('#draftPill');if(p)p.classList.toggle('show',!!show)}
function saveDraftNow(){
 if(!canvasHistory.length)return;if(mode==='math'){saveMathDraftNow();return;}
 try{state.lastDraft={key:draftKey(),data:canvas.toDataURL('image/png'),savedAt:Date.now()};localStorage.setItem(storeKey,JSON.stringify(state));setDraftPill(true)}catch(e){}
}
function dropCurrentDraft(){if(state.lastDraft?.key===draftKey()){state.lastDraft=null;save()}setDraftPill(false)}
function restoreDraftForCurrent(){
 setDraftPill(false);if(mode==='math'){restoreMathDraftForCurrent();return}const d=state.lastDraft;if(!d||d.key!==draftKey()||!d.data)return;
 const r=canvas.getBoundingClientRect();if(!r.width)return;const im=new Image();im.onload=()=>{ctx.drawImage(im,0,0,r.width,r.height);canvasHistory=[d.data];setDraftPill(true)};im.src=d.data;
}
function currentAwardKey(){const day=localDay();if(mode==='math'){const q=currentMathProblem(),sid=child().mathSession?.id||mathRunId;return q?`${day}:math:tablet:${sid}:${q.id||`${q.a}:${q.op}:${q.b}`}`:`${day}:math:tablet:none`}return `${day}:${mode}:${setId}:${currentIndex}:${current()}`}
function hasUnfinishedWriting(){const c=child(),key=currentAwardKey();return !!canvasHistory.length&&!c.awarded[key]}
