// canvas
const canvas=$('#drawCanvas'),ctx=canvas.getContext('2d');let last=null;function setPen(){const p=$('#penColor').value;ctx.strokeStyle=eraser?'#fffefc':(p==='accent'?getComputedStyle(document.body).getPropertyValue('--accent').trim():p);ctx.lineWidth=eraser?24:+$('#penWidth').value;ctx.lineCap='round';ctx.lineJoin='round'}
function resizeCanvas(){const r=$('#canvasWrap').getBoundingClientRect();if(!r.width)return;const ratio=Math.max(1,window.devicePixelRatio||1),snap=canvasHistory.at(-1);canvas.width=Math.round(r.width*ratio);canvas.height=Math.round(r.height*ratio);canvas.style.width=r.width+'px';canvas.style.height=r.height+'px';ctx.setTransform(ratio,0,0,ratio,0,0);setPen();if(snap){const im=new Image();im.onload=()=>ctx.drawImage(im,0,0,r.width,r.height);im.src=snap}}
function ppos(e){const r=canvas.getBoundingClientRect();return{x:e.clientX-r.left,y:e.clientY-r.top}}
let activePointerId=null;canvas.addEventListener('pointerdown',e=>{if(state.penOnly&&e.pointerType==='touch')return;if(!e.isPrimary&&e.pointerType==='touch')return;e.preventDefault();drawing=true;activePointerId=e.pointerId;canvas.setPointerCapture(e.pointerId);setPen();last=ppos(e);ctx.beginPath();ctx.moveTo(last.x,last.y)});canvas.addEventListener('pointermove',e=>{if(!drawing||e.pointerId!==activePointerId)return;e.preventDefault();const evs=typeof e.getCoalescedEvents==='function'?e.getCoalescedEvents():[e];for(const ev of evs){const p=ppos(ev);ctx.lineTo(p.x,p.y);ctx.stroke();last=p}});function endDraw(e){if(!drawing)return;if(e&&activePointerId!==null&&e.pointerId!==activePointerId)return;drawing=false;activePointerId=null;canvasHistory.push(canvas.toDataURL());if(canvasHistory.length>40)canvasHistory.shift();saveDraftNow()}canvas.addEventListener('pointerup',endDraw);canvas.addEventListener('pointercancel',endDraw);window.addEventListener('resize',()=>{if($('#writeView').classList.contains('active'))resizeCanvas()});
function clearCanvas(removeDraft=true){const r=canvas.getBoundingClientRect();ctx.clearRect(0,0,r.width,r.height);canvasHistory=[];if(removeDraft){if(mode==='math')deleteCurrentMathDraft();else dropCurrentDraft()}setDraftPill(false)}$('#clearBtn').addEventListener('click',()=>{if(canvasHistory.length)trackStruggle(2,'多次清除');clearCanvas(true)});$('#clearBtnSide').addEventListener('click',()=>{if(canvasHistory.length)trackStruggle(2,'多次清除');clearCanvas(true)});$('#undoBtn').addEventListener('click',()=>{if(canvasHistory.length)trackStruggle(1,'多次復原');canvasHistory.pop();const r=canvas.getBoundingClientRect();ctx.clearRect(0,0,r.width,r.height);const snap=canvasHistory.at(-1);if(snap){const im=new Image();im.onload=()=>{ctx.drawImage(im,0,0,r.width,r.height);if(state.lastDraft?.key===draftKey()){state.lastDraft={key:draftKey(),data:snap,savedAt:Date.now()};save();setDraftPill(true)}};im.src=snap}else{dropCurrentDraft()}});$('#penWidth').addEventListener('change',setPen);$('#penColor').addEventListener('change',()=>{eraser=false;$('#eraserBtn').textContent='橡皮擦';setPen()});$('#eraserBtn').addEventListener('click',()=>{eraser=!eraser;if(eraser&&canvasHistory.length)trackStruggle(1,'多次擦改');$('#eraserBtn').textContent=eraser?'✏️ 回到畫筆':'橡皮擦';setPen()});$('#penOnlyToggle').checked=!!state.penOnly;$('#penOnlyToggle').addEventListener('change',e=>{state.penOnly=e.target.checked;save();toast(state.penOnly?'✏️ 已開啟觸控筆優先':'👆 已允許手指書寫')});
