async function awardComplete(){if(completionBusy){toast('正在儲存這一題，請稍候…');return}completionBusy=true;const btn=$('#completeBtn');if(btn)btn.disabled=true;try{if(!canvasHistory.length){toast('先寫一寫再完成這一題喔 ✍️');return}const c=child(),day=localDay();if(mode==='math'){const q=currentMathProblem(),session=c.mathSession;if(!q||!session){toast('目前沒有數學題目');return}const key=currentAwardKey();if(c.awarded[key]||session.completed?.[q.id]){toast('這一題已經完成囉！');return}await saveArtworkSnapshot();if(c.awarded[key]||session.completed?.[q.id]){toast('這一題已經完成囉！');return}c.awarded[key]=1;session.completed=session.completed||{};session.completed[q.id]=Date.now();session.index=currentIndex;c.points+=5;c.done++;c.modeTotals.math=(c.modeTotals.math||0)+1;c.daily[day]=c.daily[day]||{};c.daily[day].math=(c.daily[day].math||0)+1;if(!c.practiceDates.includes(day))c.practiceDates.push(day);checkTaskBonus(c,day,'math');await deleteCurrentMathDraft();save();setDraftPill(false);toast('🎉 完成這題！+5 點');renderAll();return}const key=`${day}:${mode}:${setId}:${currentIndex}:${current()}`;if(c.awarded[key]){toast('這一題今天已領過獎勵囉！');return}if(state.autoWeak&&(Number(c.friction?.[autoReviewKey()])||0)>=3&&!c.weakItems[autoReviewKey()])c.weakItems[autoReviewKey()]={mode,value:current(),markedAt:Date.now(),times:1,success:0,auto:true,reason:'練習中修改較多'};await saveArtworkSnapshot();if(c.awarded[key]){toast('這一題今天已領過獎勵囉！');return}c.awarded[key]=1;c.points+=5;c.done++;c.modeTotals[mode]=(c.modeTotals[mode]||0)+1;c.daily[day]=c.daily[day]||{};c.daily[day][mode]=(c.daily[day][mode]||0)+1;if(!c.practiceDates.includes(day))c.practiceDates.push(day);reinforceReview(c,mode,current());resetFrictionAfterSuccess();checkTaskBonus(c,day,mode);if(state.lastDraft?.key===draftKey())state.lastDraft=null;save();setDraftPill(false);toast(state.autoGallery?'🎉 完成！+5 點，作品已收藏！':'🎉 完成！獲得 5 點獎勵！');renderAll()}finally{completionBusy=false;if(btn)btn.disabled=false}}
