function renderMathPages(){
 const per=autoMathItemsPerPage(),chunks=chunkList(mathProblems,per),total=chunks.length;
 return chunks.map((part,p)=>{const rows=`<div class="daily-math-grid">${part.map((q,i)=>`<div class="daily-math-q">${p*per+i+1}. ${q.a} ${q.op==='add'?'+':'−'} ${q.b} = ______</div>`).join('')}</div>`;return pageFrame('數字加減練習','加減法練習紙',rows,p+1,total,'square',$('#traceStyle').value,part.length,'daily-math-page')}).join('')
}
function parseCustomPrintItems(raw,splitMode='auto'){
 const value=String(raw||'').trim();if(!value)return[];
 if(splitMode==='char')return [...value.replace(/[\s,，、;；]+/g,'')].filter(Boolean).slice(0,120);
 const grouped=value.split(/[\s,，、;；]+/).filter(Boolean);
 if(splitMode==='group')return grouped.slice(0,120);
 if(grouped.length>1)return grouped.slice(0,120);
 const only=grouped[0]||'';
 if(/^[A-Za-z]+$/.test(only))return [only];
 if(/^\d+$/.test(only)&&only.length>1)return [...only].slice(0,120);
 return [...only].filter(Boolean).slice(0,120);
}
function syncCustomPrintUI(){
 const input=$('#printCustomInput'),toggle=$('#usePrintCustom'),split=$('#printCustomSplit'),status=$('#customPrintStatus');if(!input||!toggle||!split)return;
 input.value=state.printCustomText||'';toggle.checked=!!state.usePrintCustom;split.value=state.printCustomSplit||'auto';
 const n=parseCustomPrintItems(input.value,split.value).length;
 if(status)status.textContent=toggle.checked?(n?`✓ 列印時將使用自訂內容，共 ${n} 項。`:'⚠ 已啟用，但尚未輸入可列印內容。'):'尚未啟用，自訂內容不影響目前練習。';
}
