function renderShop(){const c=child();const goalSel=$('#goalGiftSelect');if(goalSel){goalSel.innerHTML='<option value="">選擇我的目標禮物</option>'+state.gifts.map(g=>`<option value="${esc(g.id)}">${esc(g.emoji||'🎁')} ${esc(g.name)}｜${g.cost} 點</option>`).join('');if(state.gifts.some(g=>String(g.id)===String(c.goalGiftId)))goalSel.value=String(c.goalGiftId);else c.goalGiftId='';const goal=state.gifts.find(g=>String(g.id)===String(c.goalGiftId));if(goal){const pct=Math.min(100,Math.round(c.points/goal.cost*100));$('#goalProgressBar').style.width=pct+'%';$('#goalProgressText').textContent=c.points>=goal.cost?`🎉 已經存夠 ${goal.name}！可以請家長確認兌換。`:`目前 ${c.points} / ${goal.cost} 點，還差 ${goal.cost-c.points} 點就能換「${goal.name}」`; }else{$('#goalProgressBar').style.width='0%';$('#goalProgressText').textContent='先選一個想努力的禮物吧！'}}$('#shopGrid').innerHTML=state.gifts.map(g=>`<div class="gift"><div class="emoji">${g.emoji||'🎁'}</div><h3>${esc(g.name)}</h3><div class="cost">⭐ ${g.cost} 點</div><p>${c.points>=g.cost?'可以兌換！':'還差 '+(g.cost-c.points)+' 點'}</p><button class="btn ${c.points>=g.cost?'good':'soft'}" data-gift="${g.id}" ${c.points<g.cost?'disabled':''}>兌換</button></div>`).join('');$('#shopGrid').querySelectorAll('button[data-gift]').forEach(b=>b.addEventListener('click',()=>redeem(state.gifts.find(g=>String(g.id)===b.dataset.gift))));$('#historyList').innerHTML=c.history.length?c.history.slice().reverse().slice(0,20).map(x=>`<div class="history-item"><span>${esc(x.name)}（-${x.cost} 點） ${x.pending?'⏳待領取':'✅已領取'}</span><span>${esc(x.time)}</span></div>`).join(''):'<div class="tiny">還沒有兌換紀錄。</div>'}
function redeem(g){const c=child();if(!g||c.points<g.cost)return;if(!state.parentPin){alert('請先請家長到「家長模式」設定 4 位數 PIN，才能兌換禮物。');return}const p=prompt(`🎁 要兌換「${g.name}」需要家長確認。\n請家長輸入 4 位數 PIN：`);if(p===null)return;if(p!==state.parentPin){alert('家長 PIN 不正確，沒有扣點。');return}if(!confirm(`確認使用 ${g.cost} 點兌換「${g.name}」嗎？`))return;c.points-=g.cost;c.redeemed++;c.history.push({id:Date.now(),name:g.name,cost:g.cost,time:new Date().toLocaleString('zh-TW'),pending:true});save();renderShop();renderBadges();alert('🎉 兌換成功！已記錄為待領取，家長可在控制台確認領取。')}
