$('#addChildBtn').addEventListener('click',()=>{const n=$('#newChildName').value.trim();if(!n)return alert('請輸入名稱');const c=newChild(n);state.children.push(c);state.activeChildId=c.id;$('#newChildName').value='';save();renderAll()});$('#addGiftBtn').addEventListener('click',()=>{const n=$('#giftName').value.trim(),cost=Math.max(1,+$('#giftCost').value||1);if(!n)return alert('請輸入禮物名稱');state.gifts.push({id:Date.now(),name:n,cost,emoji:'🎁'});$('#giftName').value='';save();renderParent();renderShop()});$('#saveTaskBtn').addEventListener('click',()=>{state.taskTarget=Math.max(1,Math.min(30,+$('#taskTarget').value||5));save();renderTasks();renderSmartDaily();alert('每日任務已更新')});$('#changePinBtn').addEventListener('click',()=>{const p=$('#newPin').value.trim();if(!/^\d{4}$/.test(p))return alert('請輸入新的 4 位數 PIN');state.parentPin=p;$('#newPin').value='';save();alert('PIN 已變更')});$('#resetChildBtn').addEventListener('click',async()=>{if(!confirm(`確定重設「${child().name}」的點數、練習紀錄與手寫作品嗎？`))return;const n=child().name,id=child().id;await deleteAllChildStoredData(id);const c=newChild(n);c.id=id;state.children=state.children.map(x=>x.id===id?c:x);save();if(mode==='math')generateMath(true);clearCanvas(false);renderAll();renderParent();toast('已完整重設目前小朋友資料')});function validateBackupPayload(raw,fileSize=0){if(fileSize>50*1024*1024)throw new Error('備份檔超過 50 MB，為避免瀏覽器記憶體不足已停止匯入');if(!raw||typeof raw!=='object'||Array.isArray(raw))throw new Error('備份格式不正確');const data=raw.state||raw;if(!data||!Array.isArray(data.children)||!data.children.length)throw new Error('備份內沒有有效的小朋友資料');if(data.children.length>30)throw new Error('備份內小朋友數量異常（最多 30 位）');if(Array.isArray(data.gifts)&&data.gifts.length>100)throw new Error('備份內禮物數量異常');const full=['kidsWritingV21-full','kidsWritingV23-full'].includes(String(raw.format||''));const artworks=full?(Array.isArray(raw.artworks)?raw.artworks:[]):[],mathDrafts=full?(Array.isArray(raw.mathDrafts)?raw.mathDrafts:[]):[];if(artworks.length>1000||mathDrafts.length>1000)throw new Error('備份內作品或暫存數量異常');const cleanArt=artworks.map((a,i)=>{const image=safeDataImage(a?.image);if(!image)throw new Error(`第 ${i+1} 張作品圖片格式不安全或過大`);return{id:safeToken(a?.id,`art-${i}-${Date.now()}`),childId:safeToken(a?.childId,''),childName:safeText(a?.childName,30),mode:['english','zhuyin','number','chinese','math','custom'].includes(a?.mode)?a.mode:'custom',value:safeText(a?.value,120),setId:safeToken(a?.setId,''),createdAt:safeNumber(a?.createdAt,0,9e15,Date.now()),day:safeText(a?.day,10),image}});const cleanDraft=mathDrafts.map((d,i)=>{const image=safeDataImage(d?.image);if(!image)throw new Error(`第 ${i+1} 筆數學暫存圖片格式不安全或過大`);return{id:safeToken(d?.id,`draft-${i}-${Date.now()}`),childId:safeToken(d?.childId,''),sessionId:safeToken(d?.sessionId,''),questionId:safeToken(d?.questionId,''),updatedAt:safeNumber(d?.updatedAt,0,9e15,Date.now()),image}});return{data:normalizeState(data),full,artworks:cleanArt,mathDrafts:cleanDraft,version:safeText(raw.version||'舊版',20),exportedAt:safeText(raw.exportedAt||'',40)}}
$('#exportBtn').addEventListener('click',async()=>{try{const artworks=await getAllStoreRecords(V20_GALLERY_STORE),mathDrafts=await getAllStoreRecords(V21_MATH_DRAFT_STORE),payload={format:'kidsWritingV23-full',version:'2.3.1',exportedAt:new Date().toISOString(),state:normalizeState(state),artworks:artworks.map(a=>Object.assign({},a,{image:safeDataImage(a.image)})).filter(a=>a.image),mathDrafts:mathDrafts.map(d=>Object.assign({},d,{image:safeDataImage(d.image)})).filter(d=>d.image)};const blob=new Blob([JSON.stringify(payload)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='兒童書寫練習_V2.3.1_完整家庭備份.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),800);toast(`💾 完整備份完成：${payload.artworks.length} 張作品`)}catch(e){alert('備份失敗：'+e.message)}});
$('#importFile').addEventListener('change',e=>{const f=e.target.files?.[0];e.target.value='';if(!f)return;if(f.size>50*1024*1024){alert('備份檔超過 50 MB，已停止匯入。');return}const reader=new FileReader();reader.onload=async()=>{try{const checked=validateBackupPayload(JSON.parse(String(reader.result||'')),f.size),data=checked.data;const when=checked.exportedAt?`\n備份時間：${checked.exportedAt}`:'';if(!confirm(`備份檢查通過。\n版本：${checked.version}${when}\n小朋友：${data.children.length} 位\n作品：${checked.artworks.length} 張\n數學暫存：${checked.mathDrafts.length} 筆\n\n確定取代目前資料嗎？`))return;state=data;if(checked.full){await replaceStoreRecords(V20_GALLERY_STORE,checked.artworks);await replaceStoreRecords(V21_MATH_DRAFT_STORE,checked.mathDrafts)}else{await replaceStoreRecords(V20_GALLERY_STORE,[]);await replaceStoreRecords(V21_MATH_DRAFT_STORE,[])}save();setTheme(state.theme||'cat');syncPaperStyle();$('#agePreset').value=state.agePreset||'preschool';$('#penOnlyToggle').checked=!!state.penOnly;$('#mathType').value=state.mathType||'mix';$('#mathMax').value=String(state.mathMax||10);$('#mathCount').value=String(state.mathCount||20);generateMath(false);clearCanvas(false);renderAll();renderParent();alert(`✅ 備份已安全還原：${checked.artworks.length} 張作品。`)}catch(err){alert('無法匯入：'+err.message)}};reader.onerror=()=>alert('無法讀取備份檔');reader.readAsText(f,'utf-8')});

