let swRegistration=null,swReloading=false;function showUpdateReady(reg){swRegistration=reg;const bar=$('#updateAppBar');if(bar)bar.hidden=false}if('serviceWorker' in navigator && /^https?:$/.test(location.protocol)){window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').then(reg=>{swRegistration=reg;if(reg.waiting)showUpdateReady(reg);reg.addEventListener('updatefound',()=>{const nw=reg.installing;if(!nw)return;nw.addEventListener('statechange',()=>{if(nw.state==='installed'&&navigator.serviceWorker.controller)showUpdateReady(reg)})});reg.update().catch(()=>{})}).catch(e=>console.warn('Service Worker 註冊失敗',e)));navigator.serviceWorker.addEventListener('controllerchange',()=>{if(swReloading)return;swReloading=true;location.reload()})}$('#updateAppBtn')?.addEventListener('click',()=>{const w=swRegistration?.waiting;if(w)w.postMessage({type:'SKIP_WAITING'});else location.reload()});$('#dismissUpdateBtn')?.addEventListener('click',()=>{$('#updateAppBar').hidden=true});

